// "What to expect": the description points of the upcoming event (Upcoming event tab of the admin dashboard).
// Shows under the Upcoming card, for every kind of event. No points written = nothing is drawn.
// You do not edit this file.
import { Icon } from './Icons';
import { Reveal } from './ui';
import { eventName, eventPoints, eventType } from './eventLive';
import { useLiveSettings } from './liveSettings';
import './EventPoints.css';

const NOUN = { hackathon: 'hackathon', workshop: 'workshop', online: 'online event' };

export default function EventPoints() {
  useLiveSettings();   // draw again when the dashboard values arrive
  const points = eventPoints();
  if (!points.length) return null;
  const name = eventName();
  return (
    <Reveal className="ep">
      <section id="event-points" aria-labelledby="ep-h">
        <span className="s-eyebrow">About this {NOUN[eventType()]}</span>
        <h2 id="ep-h" className="s-h2">{name ? `What to expect at ${name}` : 'What to expect'}</h2>
        <ul className="s-steps ep-list">
          {points.map((p, i) => (
            <li key={`${i}-${p.t}`}>
              <span className="s-step-n ep-tick" aria-hidden="true"><Icon.Check size={16} /></span>
              <div><b>{p.t}</b>{p.d ? <p>{p.d}</p> : null}</div>
            </li>
          ))}
        </ul>
      </section>
    </Reveal>
  );
}
